{
  "architect_scope": "one-R63-structural-factor-only",
  "proposal_mode": "counter_hypothesis",
  "qualitative_hypothesis": {
    "observed_bottleneck": "Lossless terminal reacquisition lets inherited generative sources dominate the upstream counter-analysis and postpones evidence settlement until policy emission.",
    "causal_change": "Permanently remove direct terminal visibility of anchor_policy, candidate_hypothesis, and loop_structure while retaining direct terminal visibility of task, anchor_contract, and task_constraints.",
    "expected_effect": "Generative evidence is synthesized earlier with reduced terminal anchor dependence, while contract reconciliation remains directly grounded at emission.",
    "falsifier": "all-valid matched majority and strict-median contract, with no score"
  },
  "structural_mutation": {
    "change_count": 1,
    "factor": "fixed generative-source edge cut with normative-source terminal visibility",
    "before": "The terminal authority reacquires all six common inputs and may reinterpret the preceding analysis against every original source.",
    "after": "The terminal authority consumes the preceding analysis and directly reacquires only task, anchor_contract, and task_constraints; direct edges from anchor_policy, candidate_hypothesis, and loop_structure are absent.",
    "why_structural": "The mutation permanently changes terminal graph connectivity and evidence authority through one source-class visibility partition, rather than renaming or splitting roles."
  },
  "mode_certificate": {
    "rejected_assumptions": [
      "Reliable policy emission requires terminal reacquisition of every common input.",
      "Inherited and counter-generative sources should remain directly co-visible at terminal authority.",
      "Upstream counter-analysis must remain defeasible through terminal rereading of its original generative sources."
    ],
    "forbidden_inherited_mechanism": "terminal lossless evidence reacquisition of all six common inputs",
    "independent_replacement_principle": "Generative evidence receives one upstream synthesis, while terminal authority directly sees only normative evidence and the resulting analysis.",
    "changed_behavioral_dimensions": [
      "terminal dependence on inherited-anchor evidence",
      "timing of generative-evidence settlement",
      "location of direct contract reconciliation"
    ],
    "counter_until_promotion": true
  },
  "candidate_structure": {
    "name": "Permanent Source-Class Cut",
    "organization": "two-call sequential lineage with an unconditional generative-source cut on the terminal edge",
    "information_flow": "The first call receives every common input and emits only an analysis that synthesizes generative evidence against normative obligations. The final call consumes that analysis, directly receives only task, anchor_contract, and task_constraints, has no direct visibility of anchor_policy, candidate_hypothesis, or loop_structure, and emits one complete policy.",
    "stages": [
      {
        "id": "source_class_cut_lineage",
        "mode": "sequential",
        "calls": [
          {
            "id": "synthesize_cut_sources",
            "role": "upstream generative-evidence synthesizer",
            "objective": "Reconcile inherited and counter-generative claims against normative obligations, preserve conflicts and supporting distinctions, and emit only an analysis without creating a policy artifact.",
            "inputs": [
              "task",
              "anchor_policy",
              "anchor_contract",
              "task_constraints",
              "candidate_hypothesis",
              "loop_structure"
            ],
            "output_type": "analysis"
          },
          {
            "id": "emit_under_normative_visibility",
            "role": "normative-source policy authority",
            "objective": "Consume synthesize_cut_sources, directly reconcile its claims with the visible normative inputs, and emit one complete policy without reacquiring the cut generative sources.",
            "inputs": [
              "synthesize_cut_sources",
              "task",
              "anchor_contract",
              "task_constraints"
            ],
            "output_type": "policy"
          }
        ]
      }
    ],
    "final_call_id": "emit_under_normative_visibility"
  },
  "compliance": {
    "one_structural_factor_only": true,
    "score_or_trace_content_used": false,
    "policy_code_emitted": false,
    "variants_sampling_or_best_of_n_emitted": false,
    "hardcoding_emitted": false
  }
}
